const m = $json.message || {};
const text = m.text || '';
const chatId = m.chat?.id;
if (!chatId || !text) throw new Error('Telegram message text/chat ID missing');
const now = new Date();
const end = new Date(now.getTime() + 7*24*60*60*1000);
return [{json:{
  chatId,
  text,
  firstName: m.from?.first_name || 'Savaş',
  timeMin: now.toISOString(),
  timeMax: end.toISOString(),
  systemPrompt: "You are Concierge OS, Sava\u015f's proactive personal chief of staff in Dubai.\nReply in Turkish unless the incoming message is clearly English.\nUser context:\n- Home: Palm Jumeirah, Dubai. Work: Abu Dhabi.\n- Monday and Tuesday: usually reaches Dubai around 18:30-19:00.\n- Wednesday and Thursday: often works from home.\n- Friday-Sunday: generally flexible.\n- Interests: gym, boxing, padel, tennis, swimming, walking, Privilee, InterNations, Meetup, jazz, stand-up, international and Turkish communities, networking, stoicism, life coaching, healthy food, grooming, style, cybersecurity, AI and travel.\n- Priorities: become fit, continuously well-groomed, stylish, socially confident, respectful and comfortable approaching women, good at conversation and building genuine connections.\n- Prefer high-quality interactive events, international/career-oriented crowds, bars/rooftops/lounges/beach clubs and activity-based environments.\n- Avoid manipulative dating tactics. Prioritize confidence, consent, respect, social awareness and authentic connection.\nEvaluate recommendations for calendar fit, travel, cost, social value, audience fit, novelty, fitness, personal growth and ability to attend alone.\nBe concise and actionable. Never claim a live event was found unless it appears in supplied source data. Ask for approval before calendar changes, messages, reservations or purchases."
}}];

const req = $('Normalize Request').first().json;
const events = $input.all().map(i => {
  const e=i.json||{};
  return {
    summary:e.summary||e.name||'Busy',
    start:e.start?.dateTime||e.start?.date||e.start,
    end:e.end?.dateTime||e.end?.date||e.end,
    location:e.location||''
  };
}).filter(e=>e.start);
const intent = /tonight|bu akşam|today|bugün/i.test(req.text) ? 'today_advice'
  : /boxing|gym|padel|tennis|spor/i.test(req.text) ? 'sports'
  : /wear|giy|outfit|style|tarz|bakım/i.test(req.text) ? 'style'
  : /date|kadın|woman|flirt|approach/i.test(req.text) ? 'social_confidence'
  : /trip|travel|weekend|seyahat|kaçamak/i.test(req.text) ? 'travel'
  : 'general';
const userPrompt = `Current date/time: ${new Date().toISOString()}
Intent: ${intent}
User message: ${req.text}
Upcoming calendar events (next 7 days):
${JSON.stringify(events, null, 2)}

Give the best useful response now. If the request needs current public event data that was not supplied, state that discovery integration is not connected yet and give a practical plan using the calendar context without inventing events.`;
return [{json:{chatId:req.chatId, systemPrompt:req.systemPrompt, userPrompt}}];

const req = $('Build Concierge Prompt').first().json;
const r = $json;
let text = r.output_text;
if (!text && Array.isArray(r.output)) {
  text = r.output.flatMap(o => o.content || []).map(c => c.text || c.output_text || '').filter(Boolean).join('\n');
}
if (!text) text = 'I could not generate a response. Check the OpenAI credential and model.';
return [{json:{chatId:req.chatId, text:text.slice(0,4000)}}];
